PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?label WHERE {
  ?z rdfs:label ?label .
  FILTER (FILTER(?label)) 
} LIMIT 50

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?label WHERE {
  ?z rdfs:label ?label .
} LIMIT 50

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?label WHERE {
  ?z rdfs:label ?label .
  FILTER (CONTAINS(?label, "Perimeter_bot_ZN_4"))
}

PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX ref: <http://w3.org/ns/rev#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?pclass ?tsid WHERE {
  ?point brick:hasLocation <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z05> .
  ?point a ?pclass .
  OPTIONAL { ?point ref:hasExternalReference ?ext . ?ext ref:hasTimeseriesId ?tsid . }
}

PREFIX ref: <https://buildgraph.org/ref#>
SELECT ?ext ?tsid ?p WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z05.Zone_Air_Temperature_Sensor> ref:hasExternalReference ?ext .
  OPTIONAL { ?ext ref:hasTimeseriesId ?tsid . }
  OPTIONAL { <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z05.Zone_Air_Temperature_Sensor> a ?p . }
}
